import numpy as np, hashlib, json
print('RAW_SOURCE',raw['source'],raw['source_ref'])
for obj in raw['objects']:
 vertices=np.asarray(obj['vertices'],float); tris=np.asarray(obj['triangles'],int); pts=vertices[tris]
 print('OBJECT',obj['name'],'id',obj['object_id'],'instance',obj['instance_id'],'triangle_count',len(tris),'bounds',[pts.reshape(-1,3).min(0).tolist(),pts.reshape(-1,3).max(0).tolist()])
 if obj['name']=='M4_Far_00':
  far=obj
  for lo,hi in [(0,511),(512,513)]:
   p=pts[lo:hi+1]; normals=np.cross(p[:,1]-p[:,0],p[:,2]-p[:,0]); normals/=np.linalg.norm(normals,axis=1)[:,None]
   edge_to_faces={}
   for face,tri in enumerate(tris[lo:hi+1],lo):
    for offset in range(3):
     edge=tuple(sorted((int(tri[offset]),int(tri[(offset+1)%3]))));edge_to_faces.setdefault(edge,[]).append(face)
   adj={face:set() for face in range(lo,hi+1)}
   for faces in edge_to_faces.values():
    for face in faces: adj[face].update(faces)
   seen=set(); queue=[lo]
   while queue:
    face=queue.pop()
    if face not in seen: seen.add(face);queue.extend(adj[face]-seen)
   print('REGION_CHECK',{'range':[lo,hi],'bounds':[p.reshape(-1,3).min(0).tolist(),p.reshape(-1,3).max(0).tolist()],'unit_normals':np.unique(normals,axis=0).tolist(),'edge_connected_triangle_count':len(seen),'boundary_edge_count':sum(len(faces)==1 for faces in edge_to_faces.values())})
 else: near=obj
x=float(near['vertices'][0][0]); d=1-x
print('WHOLE_OBJECT_DISTANCE_PROOF',{'all_far_source_triangle_vertices_x_at_least':min(far['vertices'][idx][0] for tri in far['triangles'] for idx in tri),'all_near_source_triangle_vertices_x':sorted(set(near['vertices'][idx][0] for tri in near['triangles'] for idx in tri)),'a':[1.0,0.0,0.0],'b':[x,0.0,0.0],'a_source_triangle':0,'b_source_triangle':0,'a_triangle_vertices':[far['vertices'][idx] for idx in far['triangles'][0]],'distance_m':d,'direction_a_to_b':[-1.0,0.0,0.0]})

